<h2>Check print artwork resolution</h2><p class="lead">Calculate required pixel dimensions for trim plus bleed and compare them with an existing artwork file.</p><div class="notice">This checks raster pixel density across the full document including bleed. Vector text/art is resolution-independent until rasterized, while linked images still need adequate effective PPI.</div><div class="form-grid"><div class="field"><label for="w">Trim width (inches)</label><input id="w" type="number" value="8.5" min="0.01" step="any"></div><div class="field"><label for="h">Trim height (inches)</label><input id="h" type="number" value="11" min="0.01" step="any"></div><div class="field"><label for="bleed">Bleed each edge (inches)</label><input id="bleed" type="number" value="0.125" min="0" step="any"></div><div class="field"><label for="ppi">Required image PPI</label><input id="ppi" type="number" value="300" min="1" step="any"></div><div class="field"><label for="pxw">Artwork width (pixels)</label><input id="pxw" type="number" value="2625" min="1" step="1"></div><div class="field"><label for="pxh">Artwork height (pixels)</label><input id="pxh" type="number" value="3375" min="1" step="1"></div></div><div class="tool-actions"><button class="btn btn-primary" id="calc" type="button">Calculate</button><button class="btn btn-secondary" id="reset" type="button">Reset</button></div><div class="result-box"><div class="result-grid"><div class="metric"><span>Required pixels incl. bleed</span><strong id="required">—</strong></div><div class="metric"><span>Effective artwork PPI</span><strong id="effective">—</strong></div><div class="metric"><span>Resolution check</span><strong id="status">—</strong></div><div class="metric"><span>Document size incl. bleed</span><strong id="doc">—</strong></div></div><div id="note" class="helper" style="margin-top:12px"></div></div><script>
(()=>{
const $=id=>document.getElementById(id); const num=id=>Number($(id).value); const fmt=(v,d=2)=>Number.isFinite(v)?v.toLocaleString(undefined,{maximumFractionDigits:d}):'—';
const defaults={}; document.querySelectorAll('.tool-panel input,.tool-panel select,.tool-panel textarea').forEach(el=>defaults[el.id]=el.value);
function clear(){$('required').textContent='—';$('effective').textContent='—';$('status').textContent='—';$('doc').textContent='—'; const n=$('note'); if(n){n.textContent='';n.className='helper';}}
function calculate(){try{const w=num('w'),h=num('h'),b=num('bleed'),p=num('ppi'),pw=num('pxw'),ph=num('pxh');if(!(w>0&&h>0&&b>=0&&p>0&&pw>0&&ph>0))throw 0;const dw=w+2*b,dh=h+2*b,rw=Math.ceil(dw*p),rh=Math.ceil(dh*p),ep=Math.min(pw/dw,ph/dh),ok=pw>=rw&&ph>=rh;$('required').textContent=rw+' × '+rh+' px';$('effective').textContent=fmt(ep,0)+' PPI';$('status').textContent=ok?'Meets entered PPI':'Below entered PPI';$('doc').textContent=fmt(dw,3)+' × '+fmt(dh,3)+' in';$('note').textContent='Image PPI and printer DPI are not the same specification. Use the print provider’s required artwork resolution and bleed.';}catch(e){clear(); const n=$('note'); if(n){n.textContent='Please check the inputs and try again.';n.className='helper danger';}}}
const c=$('calc'); if(c)c.addEventListener('click',calculate); const r=$('reset'); if(r)r.addEventListener('click',()=>{Object.entries(defaults).forEach(([id,v])=>{if($(id))$(id).value=v});calculate();});
document.querySelectorAll('.tool-panel input,.tool-panel select,.tool-panel textarea').forEach(el=>el.addEventListener('input',calculate));
calculate();
})();
</script>
